target.css:
:root {
  --ink: #29243d;
  --violet: #7657d8;
  --lilac: #eee9ff;
  --line: #d9d0f5;
  --paper: #ffffff;
}

.rink-pass {
  width: 420px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: var(--paper);
  color: var(--ink);
}

header {
  display: flex;
  align-items: center;
  gap: 12px;
}

.skate {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border-radius: 14px;
  background: var(--lilac);
  font-size: 26px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--violet);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.time {
  margin: 14px 0 12px;
  font-size: 14px;
}

button {
  width: 100%;
  padding: 9px;
  border: 0;
  border-radius: 9px;
  background: var(--violet);
  color: var(--paper);
  font-size: 14px;
  font-weight: 700;
}
